import fs from 'node:fs';

const p='build.mjs';
let s=fs.readFileSync(p,'utf8');
const startMarker="ppaPatchRegex(\n  'gnome realtime cannon visual',";
const nextMarker="ppaPatchRegex(\n  'archer realtime arrow visual',";
const start=s.indexOf(startMarker);
if(start<0)throw new Error('Obsolete gnome realtime cannon build hook not found');
if(s.indexOf(startMarker,start+1)>=0)throw new Error('Obsolete gnome build hook is not unique');
const next=s.indexOf(nextMarker,start);
if(next<0)throw new Error('Archer realtime visual marker not found after gnome hook');
s=s.slice(0,start)+s.slice(next);
const oldAssert="if (!output.includes(\"kind:'gnome-cannon'\")) throw new Error('Gnome realtime cannon visual patch did not apply');\n";
const n=s.split(oldAssert).length-1;
if(n!==1)throw new Error('Obsolete gnome realtime assert count '+n);
s=s.replace(oldAssert,'');
if(s.includes("'gnome realtime cannon visual'"))throw new Error('Obsolete gnome build hook survived');
if(!s.includes("'archer realtime arrow visual'"))throw new Error('Archer visual hook was damaged');
fs.writeFileSync(p,s);
console.log('Removed obsolete build.mjs gnome realtime FX hook; archer hook preserved.');
